import base64,sys
LOGO=open('logo.svg.txt').read().replace('width="34"','').replace('height="34"','')
def tile(n): return f'<span style="display:inline-grid;place-items:center;width:{n}px;height:{n}px;background:#0F172A;border-radius:22%;vertical-align:middle"><span style="display:block;width:{int(n*.78)}px;height:{int(n*.78)}px">{LOGO}</span></span>'
def img(n,w=250):
    d=base64.b64encode(open('img/'+n+'.png','rb').read()).decode()
    return f'<img src="data:image/png;base64,{d}" style="width:{w}px;border-radius:14px;border:1px solid #BFDBFE">'
CSS='''@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;font-family:Inter,'DejaVu Sans',sans-serif;color:#0F172A;font-size:13.5px;line-height:1.6}
.pg{width:210mm;height:297mm;padding:16mm 16mm 18mm;position:relative;page-break-after:always;overflow:hidden;background:#fff}
.bar{background:linear-gradient(135deg,#2563EB,#0EA5E9);color:#fff;border-radius:18px;padding:12px 18px;margin:-4mm 0 18px;box-shadow:0 6px 16px rgba(37,99,235,.25)}
.bar b{font-size:20px}.bar span{display:block;font-size:11px;opacity:.9}
h1{font-size:25px;margin:0 0 8px;color:#1D4ED8;padding-bottom:6px;border-bottom:3px solid #38BDF8;display:inline-block}h2{font-size:16px;margin:16px 0 6px;color:#0F172A;padding-left:10px;border-left:4px solid #2563EB}
.cover{background:linear-gradient(160deg,#1D4ED8,#2563EB 45%,#38BDF8);color:#fff;padding:38mm 20mm}.cover .c1,.cover .c2{position:absolute;border-radius:50%;background:rgba(255,255,255,.10)}.cover .c1{width:300px;height:300px;right:-90px;top:-70px}.cover .c2{width:420px;height:420px;left:-150px;bottom:-160px}.chip{display:inline-block;background:rgba(255,255,255,.2);border:1px solid rgba(255,255,255,.5);border-radius:99px;padding:6px 16px;margin:0 6px 6px 0;font-size:13px;font-weight:700}table{border-radius:10px;overflow:hidden}.cover h1{border:0;display:block;color:#fff;font-size:56px;letter-spacing:.02em}.cover p{font-size:16px}
.ft{position:absolute;left:16mm;right:16mm;bottom:8mm;font-size:10px;color:#64748B;display:flex;justify-content:space-between}
.row{display:flex;gap:16px;align-items:flex-start}.col{flex:1}.shots{display:flex;gap:18px;justify-content:center;margin-top:12px}img{box-shadow:0 8px 22px rgba(37,99,235,.22)}
.box{background:#EFF6FF;border-left:4px solid #2563EB;border-radius:8px;padding:8px 12px;margin:8px 0}.warn{background:#FEF3C7;border-color:#D97706}
ul{padding-left:20px;margin:6px 0}li{margin:5px 0}ul li::marker{color:#2563EB}ol{list-style:none;counter-reset:s;padding:0;margin:8px 0}ol li{counter-increment:s;position:relative;background:#F1F6FF;border-radius:12px;padding:9px 12px 9px 46px;margin:7px 0}ol li::before{content:counter(s);position:absolute;left:11px;top:50%;transform:translateY(-50%);width:26px;height:26px;border-radius:50%;background:linear-gradient(135deg,#2563EB,#0EA5E9);color:#fff;font-weight:800;text-align:center;line-height:26px;font-size:13px}.cap{font-size:10.5px;color:#64748B;text-align:center;margin-top:4px}
table{border-collapse:collapse;width:100%}td,th{border:1px solid #BFDBFE;padding:5px 8px;text-align:left}th{background:#DBEAFE}'''
def page(n,body,total,title):
    return f'<div class="pg"><div class="bar" style="display:flex;gap:12px;align-items:center">{tile(40)}<div><b>MAH</b><span>Missing App Home · {title}</span></div></div>{body}<div class="ft"><span>© 2026 Nguyễn Tấn Tài (Missing) · Dùng miễn phí, cấm bán lại</span><span>{n}/{total}</span></div></div>'
def cover(t,s): return f'<div class="pg cover"><div class="c1"></div><div class="c2"></div>{tile(120)}<h1 style="margin-top:14px">MAH</h1><p style="font-size:20px;margin-top:0">Missing App Home</p><h1 style="font-size:28px;margin-top:40mm">{t}</h1><p>{s}</p><p style="margin-top:34mm"><span class="chip">Windows</span><span class="chip">Mac</span><span class="chip">Android</span><span class="chip">iPhone · iPad</span><span class="chip">Dùng được offline</span></p><p style="margin-top:30mm;font-size:12px;opacity:.9;position:relative">© 2026 Nguyễn Tấn Tài (Missing) · Miễn phí, cấm bán lại</p></div>'
def doc(name,pages,title):
    h='<html><head><meta charset="utf-8"><style>'+CSS+'</style></head><body>'+cover(*title[:2])+''.join(page(i+2,b,len(pages)+1,title[2]) for i,b in enumerate(pages))+'</body></html>'
    open(name,'w').write(h)
# ---------- GIỚI THIỆU ----------
gt=[
f'''<h1>MAH là gì?</h1><p>MAH là ứng dụng quản lý nhà cho thuê, <b>miễn phí</b>, chạy trên điện thoại và máy tính. Dữ liệu lưu ngay trên máy của chủ nhà, <b>dùng được cả khi không có mạng</b>.</p>
<h2>Dành cho 4 loại hình</h2><table><tr><th>Loại</th><th>Cách quản lý</th></tr><tr><td>Nhà trọ</td><td>Theo phòng, thu điện nước theo số công tơ</td></tr><tr><td>Chung cư mini</td><td>Theo căn hộ, dịch vụ cố định (thang máy, gửi xe...)</td></tr><tr><td>Ký túc xá</td><td>Theo từng giường trong phòng</td></tr><tr><td>Home (nhà nguyên căn, homestay)</td><td>Đặt phòng theo lịch ngày</td></tr></table>
<div class="row" style="margin-top:12px"><div class="col"><h2>Làm được gì</h2><ul><li>Quản lý nhiều nhà trong một app</li><li>Phòng, giường, khách thuê, hợp đồng</li><li>Chốt điện nước hằng tháng, tự tạo hóa đơn</li><li>Chọn ngày chốt tiền: ngày 5, 10, 20 hoặc ngày tự chọn</li><li>Thêm dịch vụ riêng (rác, wifi, gửi xe...)</li><li>Thu tiền, sổ thu chi, công nợ</li><li>Sự cố, tài sản trong phòng</li><li>Báo cáo lọc theo năm, tháng, xuất Excel đẹp</li></ul></div><div class="col" style="text-align:center">{img('welcome',260)}<div class="cap">Màn hình chào lần đầu mở app</div></div></div>''',
f'''<h1>Tổng quan và phòng</h1><div class="shots">{img('home',255)}{img('units',255)}</div><div class="cap">Tổng quan: tiền còn phải thu, đã thu, phòng đang thuê, lịch chốt · Danh sách phòng và trạng thái</div>
<h2>Điểm chính</h2><ul><li>Tổng quan nhắc ngày chốt và những khách cần nhắc đóng tiền.</li><li>Phòng có các trạng thái: trống, đang thuê, sắp hết hạn.</li><li>Mỗi nhà có giá điện, nước và dịch vụ riêng; chủ nhà tự thêm, sửa, xóa.</li></ul>''',
f'''<h1>Chốt điện nước và hóa đơn</h1><div class="shots">{img('chot',255)}{img('bills',255)}</div><div class="cap">Nhập số điện nước mới, app tính tiền · Hóa đơn: tìm theo tên, lọc theo tháng, năm</div>
<ul><li>Số cũ lấy từ lần chốt trước, app báo lỗi nếu nhập số nhỏ hơn số cũ.</li><li>Hóa đơn có thể giảm giá hoặc phụ thu, thu một phần hoặc thu đủ.</li></ul>''',
f'''<h1>Nhắc đóng tiền qua Zalo hoặc SMS</h1><div class="row"><div class="col"><p>Bấm <b>Nhắc</b> ở khách còn nợ. App soạn sẵn tin nhắn lịch sự, đủ số tiền, tài khoản nhận và nội dung chuyển khoản.</p><ul><li><b>SMS</b>: mở sẵn tin nhắn, <b>dùng được khi không có mạng</b> (cần SIM).</li><li><b>Zalo</b>: app chép sẵn tin nhắn rồi mở Zalo, <b>cần có mạng</b>. Dán tin vào cuộc trò chuyện là gửi.</li><li>Chủ nhà tự sửa mẫu tin trong Cài đặt.</li></ul></div><div class="col" style="text-align:center">{img('remind',260)}</div></div>''',
f'''<h1>Báo cáo, Excel và dữ liệu</h1><div class="row"><div class="col" style="text-align:center">{img('report',260)}</div><div class="col"><ul><li>Báo cáo lọc theo năm, tháng.</li><li>Xuất Excel gồm các trang: Tổng hợp, Hóa đơn, Thu chi, Công nợ. Xuất được cả khi không có mạng.</li><li><b>Sao lưu ra file</b> và <b>khôi phục từ file</b>.</li><li>App tự giữ 8 bản dự phòng trong máy.</li></ul><div class="box warn"><b>Lưu ý:</b> dữ liệu nằm trên máy này, không tự đồng bộ giữa các máy. Hãy sao lưu ra file định kỳ và cất ở Drive, iCloud hoặc gửi qua Zalo. Xóa dữ liệu trình duyệt hoặc gỡ app có thể làm mất dữ liệu.</div></div></div>'''
]
doc('MAH-Gioi-thieu-chuc-nang.html',gt,('Giới thiệu chức năng','Quản lý nhà trọ, chung cư mini, ký túc xá, homestay. Miễn phí.','Giới thiệu chức năng'))
