# ---------- HƯỚNG DẪN SỬ DỤNG ----------
def two(left,i1,cap1,i2=None,cap2='',w=250):
    r=f'<div class="shots" style="margin-top:10px">{img(i1,w)}'+(img(i2,w) if i2 else '')+'</div>'
    return left+r+f'<div class="cap">{cap1}{(" · "+cap2) if cap2 else ""}</div>'
su=[
'''<h1>Bắt đầu nhanh trong 6 bước</h1><p>Làm lần lượt, mất khoảng 10 phút cho một nhà.</p><ol><li><b>Tạo nhà</b>: tên, địa chỉ, loại hình.</li><li><b>Thêm phòng</b> (hoặc căn, giường) và giá thuê.</li><li><b>Cài đặt</b> giá điện, nước, dịch vụ, ngày chốt, tài khoản nhận tiền.</li><li><b>Cho thuê</b>: nhập khách và hợp đồng cho từng phòng.</li><li><b>Chốt điện nước</b> mỗi tháng, app tạo hóa đơn.</li><li><b>Thu tiền</b> và <b>nhắc</b> khách chưa đóng.</li></ol><div class="box">Muốn tập trước: ở màn hình chào bấm <b>Xem thử dữ liệu mẫu</b>, bấm thử mọi nút, xong vào Cài đặt bấm <b>Xóa dữ liệu mẫu</b>.</div><h2>Thanh menu</h2><table><tr><th>Mục</th><th>Dùng để</th></tr><tr><td>Tổng quan</td><td>Tiền còn phải thu, nhắc chốt, khách cần nhắc</td></tr><tr><td>Phòng</td><td>Danh sách phòng, thêm, sửa, cho thuê</td></tr><tr><td>Hóa đơn</td><td>Tìm, lọc, thu tiền, giảm giá hoặc phụ thu</td></tr><tr><td>Báo cáo</td><td>Lọc theo năm, tháng, xuất Excel</td></tr><tr><td>Thêm</td><td>Khách thuê, hợp đồng, thu chi, sự cố, tài sản, cài đặt</td></tr></table>''',
two('<h1>1. Tạo nhà và thêm phòng</h1><ol><li>Màn hình chào: bấm <b>Tạo nhà đầu tiên</b>. Nhập tên nhà, địa chỉ, chọn loại hình (nhà trọ, chung cư mini, ký túc xá, home). Bấm <b>Tạo nhà</b>.</li><li>Vào tab <b>Phòng</b>, bấm <b>Thêm phòng</b>. Nhập tên hoặc số phòng, tầng, giá thuê mỗi tháng. Bấm <b>Lưu</b>.</li></ol><p>Có nhiều nhà: bấm tên nhà ở góc trên để đổi nhà hoặc thêm nhà mới. Chọn loại hình xong trước khi thêm phòng, vì sau khi có phòng thì không đổi được loại.</p>','g_house','Tạo nhà','g_unitform','Thêm phòng'),
two('<h1>2. Cho thuê và hợp đồng</h1><ol><li>Ở tab Phòng, bấm vào một phòng <b>Trống</b>, chọn <b>Cho thuê</b>.</li><li>Nhập họ tên, số điện thoại (cần để nhắc tiền), CCCD nếu có, số người ở, ngày bắt đầu, kỳ hạn, giá thuê, tiền cọc.</li><li>Bấm <b>Lưu hợp đồng</b>. Phòng chuyển sang <b>Đang thuê</b>.</li></ol><p>Khi khách dọn đi: bấm phòng, chọn <b>Trả phòng</b>. Hết hạn muốn tiếp tục: chọn <b>Gia hạn</b>. Có thể xem mẫu hợp đồng và in hoặc lưu PDF.</p><div class="box">Ký túc xá: mỗi giường là một chỗ thuê riêng. Home (homestay): dùng tab <b>Đặt phòng</b> để thêm đặt phòng, xem lịch 14 ngày, nhận phòng và trả phòng.</div>','g_unitdetail','Chi tiết phòng','g_rent','Cho thuê'),
two('<h1>3. Cài đặt một lần</h1><p>Vào <b>Thêm, Cài đặt</b>:</p><ul><li><b>Giá điện, nước</b> và <b>dịch vụ hằng tháng</b> (rác, wifi, gửi xe...). Bấm Thêm để tạo dịch vụ riêng, bấm Xóa để bỏ.</li><li><b>Lịch chốt</b>: chọn ngày 5, 10, 20 hoặc tự đặt ngày từ 1 đến 28.</li><li><b>Tài khoản nhận tiền</b>: ngân hàng, số tài khoản, tên chủ. Tin nhắc sẽ ghi sẵn.</li><li><b>Mẫu tin nhắc</b>: sửa lời lẽ, giữ các mục {tên} {phòng} {tháng} {số tiền} {hạn} {tk}.</li></ul>','set','Cài đặt','chot','Chốt điện nước'),
'''<h1>4. Chốt điện nước hàng tháng</h1><ol><li>Tổng quan, bấm <b>Chốt điện nước</b> (app nhắc khi đến ngày chốt).</li><li>Nhập số điện, số nước mới của từng phòng. Số cũ lấy từ lần trước. Nhập nhỏ hơn số cũ thì app báo đỏ.</li><li>Bấm <b>Tạo hóa đơn</b>. Mỗi phòng có hóa đơn gồm tiền phòng, điện, nước, dịch vụ.</li></ol><div class="box">Số mới nhập sai? Phòng đã tạo hóa đơn thì sửa bằng <b>Giảm giá hoặc phụ thu</b> trong hóa đơn.</div>'''+f'<div class="shots">{img("chot",255)}</div>',
two('<h1>5. Hóa đơn và thu tiền</h1><ol><li>Tab <b>Hóa đơn</b>: tìm theo tên khách hoặc phòng, lọc theo năm, tháng, và trạng thái (chưa thu, đã thu).</li><li>Bấm một hóa đơn, bấm <b>Thu tiền</b>. Nhập số tiền khách đưa, hình thức, ngày. Bấm <b>Ghi nhận</b>.</li><li>Thu thiếu thì hóa đơn thành <b>Thu một phần</b>, phần còn lại vẫn theo dõi.</li><li><b>Giảm giá hoặc phụ thu</b> khi cần điều chỉnh. <b>Chia sẻ</b> để gửi hóa đơn cho khách.</li></ol>','g_inv','Hóa đơn','g_pay','Thu tiền'),
two('<h1>6. Nhắc đóng tiền</h1><ol><li>Tổng quan hoặc Hóa đơn: bấm <b>Nhắc thu tiền</b>. App đi lần lượt từng khách còn nợ.</li><li>Xem tin nhắn soạn sẵn, bấm <b>Gửi bằng SMS</b> hoặc <b>Gửi bằng Zalo</b>.</li><li>Zalo: app chép sẵn tin, mở Zalo, bạn dán tin vào cuộc trò chuyện rồi gửi. Cần có mạng.</li><li>SMS: mở sẵn tin nhắn, dùng được khi không có mạng, cần SIM.</li><li>Không muốn nhắc khách này: bấm <b>Bỏ qua khách này</b>.</li></ol>','remind','Nhắc tiền','home','Tổng quan'),
two('<h1>7. Thu chi và sự cố</h1><ul><li><b>Thu chi</b> (Thêm, Thu chi): bấm <b>Thêm khoản chi</b> hoặc <b>Thêm khoản thu khác</b>. Chọn loại, nhập nội dung, số tiền, ngày. Có nút Sửa, Xóa. Tiền phòng thu từ hóa đơn tự vào sổ.</li><li><b>Sự cố</b>: bấm <b>Báo sự cố</b> (hỏng điện, nước...), rồi <b>Nhận xử lý</b> và <b>Đánh dấu đã xong</b>.</li><li><b>Tài sản</b>: ghi đồ trong phòng, có bộ tài sản mặc định.</li></ul>','g_cash','Thu chi','g_issues','Sự cố'),
two('<h1>8. Báo cáo và Excel</h1><ul><li>Tab <b>Báo cáo</b>: chọn năm, tháng để xem doanh thu, tỷ lệ thu, công nợ.</li><li>Bấm <b>Xuất Excel</b>: file có các trang Tổng hợp, Hóa đơn, Thu chi, Công nợ. Điện thoại hiện bảng chia sẻ để lưu hoặc gửi Zalo, máy tính tải về thư mục Tải xuống.</li><li>Xuất được cả khi không có mạng.</li></ul><h2>Sao lưu</h2><p>Cài đặt, bấm <b>Sao lưu ra file</b> mỗi tuần và cất ở Drive, iCloud hoặc gửi qua Zalo. Đổi máy: cài MAH, bấm <b>Khôi phục từ file</b>.</p><div class="box warn">Dữ liệu chỉ nằm trên máy này. Đừng xóa dữ liệu trình duyệt hoặc gỡ app khi chưa sao lưu.</div>','report','Báo cáo','g_more','Menu Thêm'),
]
doc('MAH-Huong-dan-su-dung.html',su,('Hướng dẫn sử dụng','Từ tạo nhà đến thu tiền và báo cáo, từng bước có hình.','Hướng dẫn sử dụng'))
